<!DOCTYPE html>
<html lang="tr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AKAĞİTİM - Eğitim ve Danışmanlık Hizmetleri</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <!-- Header -->
    <header class="header">
        
        <!-- Main Header -->
        <div class="main-header">
            <div class="container">
                <div class="header-inner">
                    <div class="logo">
                        <div class="logo-icon"></div>
                        <div class="logo-text">
                            <div class="logo-title">AKAĞİTİM</div>
                            <div class="logo-subtitle">Eğitim ve Danışmanlık Hizmetleri</div>
                        </div>
                    </div>
                    
                    <nav class="nav-menu">
                        <a href="#ana-sayfa">Ana Sayfa</a>
                        <a href="#hakkimizda">Hakkımızda</a>
                        <a href="#dil-okullari">Dil Okulları</a>
                        <a href="#universite">Üniversite</a>
                        <a href="#ogretmen-hareketliligi">Öğretmen Hareketliliği</a>
                        <a href="#iletisim">İletişim</a>
                    </nav>
                    
                    <div class="header-social">
                        <a href="#" aria-label="Instagram">IG</a>
                        <a href="#" aria-label="Facebook">FB</a>
                        <a href="#" aria-label="X">X</a>
                    </div>
                    
                    <button class="mobile-menu-toggle" aria-label="Menüyü aç/kapat">
                        <span></span>
                        <span></span>
                        <span></span>
                    </button>
                </div>
            </div>
        </div>
    </header>

    <main>
        <!-- Hero Slider -->
        <section class="hero-slider">
            <div class="container">
                <div class="hero-content">
                    <div class="hero-text">
                        <p class="hero-eyebrow">Öğretmen Dokunuşuyla</p>
                        <h1 class="hero-title">Dünya Keşfi</h1>
                        <p class="hero-description">AKA'da eğitime dair her yolculuk bir öğretmen eşliğinde başlar ve öğretmen eşliğinde tamamlanır.</p>
                        <div class="hero-buttons">
                            <a href="#iletisim" class="btn btn-primary">Ücretsiz Danışmanlık →</a>
                            <a href="#programlar" class="btn btn-secondary">Programları İncele</a>
                        </div>
                        <div class="slider-dots">
                            <span class="dot active"></span>
                            <span class="dot"></span>
                            <span class="dot"></span>
                        </div>
                    </div>
                    <div class="hero-image">
                        <div class="hero-image-placeholder"></div>
                        <div class="hero-badge">
                            <span class="badge-icon">✋⭐</span>
                        </div>
                    </div>
                </div>
                <button class="slider-arrow slider-arrow-prev" aria-label="Önceki">‹</button>
                <button class="slider-arrow slider-arrow-next" aria-label="Sonraki">›</button>
            </div>
        </section>

        <!-- İstatistik Section -->
        <section class="stats-section">
            <div class="container">
                <div class="stats-header">
                    <h2 class="stats-title">Bizimle Yol Yürümeye<br>Var Mısınız?</h2>
                    <p class="stats-description">Türkiye’nin farklı şehirlerinde ofislerimiz ve deneyimli
                        temsilcilerimiz sizlere en iyi hizmeti sunmak için hazır.
                        Harita üzerinde şehirlere tıklayarak
                        temsilciliklerimizi görebilirsiniz.</p>
                </div>
                
                <div class="stats-main">
                    <!-- Dünya Küresi -->
                    <div class="globe-icon"></div>
                    
                    <!-- Sol Kartlar -->
                    <div class="stat-card stat-card-left stat-card-left-top">
                        <h3 class="stat-number">12</h3>
                        <span class="stat-label">Şehirde Ofisimiz</span>
                    </div>

                    <div class="stat-card stat-card-left stat-card-left-bottom">
                        <h3 class="stat-number">50+</h3>
                        <span class="stat-label">Deneyimli Temsilci</span>
                    </div>
                    
                    
                    <!-- Sağ Kart -->
                    <div class="stat-card stat-card-right">
                        <h3 class="stat-number">7/24</h3>
                        <span class="stat-label">Destek Hattı</span>
                        <small class="stat-small">Danışmanlarımız hedef ülkeye göre süreç planı çıkarır.</small>
                        <a href="#iletisim" class="btn btn-outline-white">Detaylı Bilgi Alın</a>
                    </div>
                    
                    <!-- Türkiye Haritası -->
                    
