    <script src="instagram-config.js"></script>
    <script>
        // Mobile menu toggle (optional chaining kullanmadan, eski tarayıcı uyumlu)
        (function () {
            var menuToggle = document.querySelector('.mobile-menu-toggle');
            var navMenu = document.querySelector('.nav-menu');
            if (menuToggle && navMenu) {
                menuToggle.addEventListener('click', function () {
                    navMenu.classList.toggle('active');
                });
            }
        }());

        // Harita şehir tıklama
        (function () {
            var cityPaths = document.querySelectorAll('.turkey-map path[name]');
            for (var i = 0; i < cityPaths.length; i++) {
                (function (city) {
                    city.style.pointerEvents = 'auto';
                    city.addEventListener('click', function () {
                        var name = city.getAttribute('name') || city.getAttribute('data-city') || 'Seçilen il';
                        alert(name + ' temsilciliği');
                    });
                }(cityPaths[i]));
            }
        }());

        // Instagram native embed (@aka_egitim – instagram-config.js’deki URL’ler)
        (function () {
            var urls = window.INSTAGRAM_POST_URLS;
            if (!urls || !urls.length) return;
            var grid = document.getElementById('instagram-feed');
            if (!grid) return;
            for (var i = 0; i < urls.length; i++) {
                var wrap = document.createElement('div');
                wrap.className = 'instagram-item';
                var bq = document.createElement('blockquote');
                bq.className = 'instagram-media';
                bq.setAttribute('data-instgrm-permalink', urls[i]);
                bq.setAttribute('data-instgrm-captioned', '');
                wrap.appendChild(bq);
                grid.appendChild(wrap);
            }
            var s = document.createElement('script');
            s.async = true;
            s.src = 'https://www.instagram.com/embed.js';
            s.onload = function () {
                if (window.instgrm && window.instgrm.Embeds) window.instgrm.Embeds.process();
            };
            document.body.appendChild(s);
        }());
    </script>
</body>
</html>
